// Create an EssentiaException with a fuzzed message and verify what() returns it
std::string msg = FUZZ_PARAM_STR();
essentia::EssentiaException ex(msg);
const char* w = ex.what();
// Validate contract: what() must return a non-null C-string containing the stored message
FUZZ_ASSERT(w != 0, "EssentiaException::what returned null");
FUZZ_ASSERT(std::string(w) == msg, "EssentiaException::what content mismatch");
// Validation: The stub constructs a local exception, calls what(), and asserts non-null and content equality. No persistent objects are leaked or returned.

// Generate two arbitrary bytes and compare case-insensitively
unsigned int aU = *FUZZ_PARAM(unsigned int);
unsigned int bU = *FUZZ_PARAM(unsigned int);
char a = static_cast<char>(aU & 0xFF);
