import random
import string
from typing import List

# Data type: arbitrary string
# Used across many stubs as: general messages, map keys, specs for Range/Interval/Set,
# descriptor names, logger messages, etc. We aim to generate interesting but valid strings
# covering: ASCII words, digits, punctuation, whitespace, unicode-like bytes, bracketed specs,
# comma-separated sets, interval-like expressions, file/path-like tokens, and varying sizes.

_MAX_SIZE = 4096

def _rand(rng: random.Random, n_min: int, n_max: int) -> int:
    return rng.randint(n_min, n_max)

def _weighted_choice(rng: random.Random, items: List[str]) -> str:
    return rng.choice(items)

def _make_ascii_word(rng: random.Random, min_len=1, max_len=16) -> str:
    n = _rand(rng, min_len, max_len)
    alphabet = string.ascii_letters + string.digits + "_"
    return ''.join(rng.choice(alphabet) for _ in range(n))

def _make_whitespacey(rng: random.Random, min_len=0, max_len=32) -> str:
    n = _rand(rng, min_len, max_len)
    pool = [' ', '\t', '\n', '\r', '\v', '\f']
    return ''.join(rng.choice(pool) for _ in range(n))

def _make_punct(rng: random.Random, min_len=1, max_len=16) -> str:
    n = _rand(rng, min_len, max_len)
    pool = "-_.:,;!@#$%^&*()+={}[]|/\\?~`'\""
    return ''.join(rng.choice(pool) for _ in range(n))

def _make_utf8ish_bytes(rng: random.Random, min_len=1, max_len=24) -> bytes:
    # Generate bytes that are often valid UTF-8 sequences mixed with arbitrary bytes
    n = _rand(rng, min_len, max_len)
    out = bytearray()
    while len(out) < n:
        choice = rng.random()
        if choice < 0.6:
            out.append(rng.randrange(0x20, 0x7F))  # printable ASCII
        elif choice < 0.8:
            # 2-byte UTF-8
            b1 = rng.randrange(0xC2, 0xDF + 1)
            b2 = rng.randrange(0x80, 0xBF + 1)
            out.extend([b1, b2])
        elif choice < 0.95:
            # 3-byte UTF-8
            b1 = rng.randrange(0xE0, 0xEF + 1)
            b2 = rng.randrange(0x80, 0xBF + 1)
            b3 = rng.randrange(0x80, 0xBF + 1)
            out.extend([b1, b2, b3])
        else:
            out.append(rng.randrange(0x00, 0x100))
    return bytes(out[:n])

def _interval_spec(rng: random.Random) -> str:
    # Forms like: [a,b], (a,b), [a,inf), (-inf,b], singletons, or open-ended
    lb_incl = _weighted_choice(rng, ['[', '('])
    ub_incl = _weighted_choice(rng, [']', ')'])
    # pick numeric bounds (floats)
    def num():
        # mix ints, floats, scientific
        kind = _rand(rng, 0, 3)
        if kind == 0:
            return str(_rand(rng, -100000, 100000))
        elif kind == 1:
            return f"{rng.uniform(-1e6, 1e6):.6f}"
        elif kind == 2:
            return f"{rng.uniform(-1e3, 1e3):.3e}"
        else:
            return f"{rng.uniform(-1e3, 1e3)}"
    # sometimes use inf/-inf
    a_inf = rng.random() < 0.2
    b_inf = rng.random() < 0.2
    a = "-inf" if a_inf else num()
    b = "inf" if b_inf else num()
    # Ensure order sometimes swapped to exercise parsing
    if not a_inf and not b_inf and rng.random() < 0.5:
        try:
            fa = float(a)
            fb = float(b)
            if fa > fb:
                a, b = b, a
        except Exception:
            pass
    return f"{lb_incl}{a},{b}{ub_incl}"

def _set_spec(rng: random.Random) -> str:
    # Forms like: {a,b,c} or comma-separated without braces
    n = _rand(rng, 1, 8)
    elems = []
    for _ in range(n):
        # elements may include spaces and punctuation but avoid braces/commas inside
        token = _make_ascii_word(rng, 1, 10)
        if rng.random() < 0.3:
            token += _make_punct(rng, 0, 3)
        elems.append(token)
    core = ','.join(elems)
    if rng.random() < 0.7:
        return '{' + core + '}'
    return core

def _pathish(rng: random.Random) -> str:
    parts = [_make_ascii_word(rng, 1, 8) for _ in range(_rand(rng, 1, 5))]
    sep = _weighted_choice(rng, ['/', '\\'])
    root = ''
    if rng.random() < 0.5:
        root = sep
    elif rng.random() < 0.2:
        # Windows drive
        root = rng.choice(string.ascii_letters) + ':' + sep
    return root + sep.join(parts)

def _comma_list(rng: random.Random) -> str:
    n = _rand(rng, 1, 12)
    parts = []
    for i in range(n):
        parts.append(_make_ascii_word(rng, 1, 10))
    # Randomly add spaces around commas
    glue = _weighted_choice(rng, [',', ', ', ' ,', ' , '])
    return glue.join(parts)

def _logger_msg(rng: random.Random) -> str:
    # Include timestamps, module tags, and random content
    ts = f"{_rand(rng,1970,2099)}-{_rand(rng,1,12):02d}-{_rand(rng,1,28):02d}T{_rand(rng,0,23):02d}:{_rand(rng,0,59):02d}:{_rand(rng,0,59):02d}"
    mod = _weighted_choice(rng, ["EAlgorithm","EConnectors","EFactory","ENetwork","EGraph","EExecution","EMemory","EScheduler"]) \
          + ':'
    text = _make_ascii_word(rng, 3, 12) + ' ' + _make_ascii_word(rng, 3, 12)
    if rng.random() < 0.5:
        text += ' ' + _comma_list(rng)
    return f"[{ts}] {mod} {text}"

def _ordered_map_key(rng: random.Random, idx: int) -> str:
    base = _make_ascii_word(rng, 1, 8)
    return f"{base}{idx}"

def _range_spec(rng: random.Random) -> str:
    # Sometimes Everything, sometimes interval, sometimes set
    kind = _rand(rng, 0, 4)
    if kind == 0:
        return "*"  # hypothetical everything
    if kind == 1:
        return "Everything"  # named variant
    if kind == 2:
        return _interval_spec(rng)
    return _set_spec(rng)

def _bounded_concat(parts: List[bytes], limit: int = _MAX_SIZE) -> bytes:
    out = bytearray()
    for p in parts:
        if not p:
            continue
        remain = limit - len(out)
        if remain <= 0:
            break
        out.extend(p[:remain])
    return bytes(out)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose a scenario shaping the string for different consumers
    scenario = _rand(rng, 0, 11)

    chunks: List[bytes] = []

    if scenario == 0:
        # Logger-like message
        s = _logger_msg(rng)
        chunks.append(s.encode('utf-8', errors='ignore'))
    elif scenario == 1:
        # Range spec: Interval/Set/Everything
        s = _range_spec(rng)
        chunks.append(s.encode('utf-8', errors='ignore'))
    elif scenario == 2:
        # Comma-separated list
        s = _comma_list(rng)
        chunks.append(s.encode('utf-8', errors='ignore'))
    elif scenario == 3:
        # Path-like content
        s = _pathish(rng)
        chunks.append(s.encode('utf-8', errors='ignore'))
    elif scenario == 4:
        # OrderedMap/ParameterMap key-like safe token
        n = _rand(rng, 1, 8)
        parts = [_ordered_map_key(rng, i) for i in range(n)]
        s = '.'.join(parts)
        chunks.append(s.encode('utf-8', errors='ignore'))
    elif scenario == 5:
        # Interval explicitly with spaces and varied formatting
        s = _interval_spec(rng)
        if rng.random() < 0.5:
            s = ' ' * _rand(rng, 0, 3) + s + ' ' * _rand(rng, 0, 3)
        chunks.append(s.encode('utf-8', errors='ignore'))
    elif scenario == 6:
        # Set spec with braces and spaces
        s = _set_spec(rng)
        if rng.random() < 0.5:
            s = s.replace(',', ', ')
        chunks.append(s.encode('utf-8', errors='ignore'))
    elif scenario == 7:
        # General text with whitespace and punctuation
        s = _make_ascii_word(rng, 3, 12) + _make_whitespacey(rng, 1, 5) + _make_punct(rng, 1, 5) \
            + _make_whitespacey(rng, 0, 3) + _make_ascii_word(rng, 3, 12)
        chunks.append(s.encode('utf-8', errors='ignore'))
    elif scenario == 8:
        # UTF-8-ish bytes blended with ascii header/footer
        head = _make_ascii_word(rng, 0, 8).encode('ascii', errors='ignore')
        core = _make_utf8ish_bytes(rng, 8, 64)
        tail = _make_punct(rng, 0, 8).encode('ascii', errors='ignore')
        chunks.extend([head, core, tail])
    elif scenario == 9:
        # Tokenize/strip friendly string with mixed delimiters
        parts = []
        for _ in range(_rand(rng, 3, 10)):
            parts.append(_make_ascii_word(rng, 1, 8))
        delims = _weighted_choice(rng, [' ', ',', '\t', '|', ':'])
        s = delims.join(parts)
        # add leading/trailing spaces to exercise strip
        s = _whitespace_pad(rng, s)
        chunks.append(s.encode('utf-8', errors='ignore'))
    elif scenario == 10:
        # Key/value like line to feed into generic uses
        key = _make_ascii_word(rng, 3, 10)
        val = _make_ascii_word(rng, 3, 12)
        sep = _weighted_choice(rng, ['=', ':', ' -> '])
        s = f"{key}{sep}{val}"
        chunks.append(s.encode('utf-8', errors='ignore'))
    else:
        # Mixed large blob but bounded
        piece_count = _rand(rng, 2, 8)
        for _ in range(piece_count):
            choice = _rand(rng, 0, 6)
            if choice == 0:
                chunks.append(_make_ascii_word(rng, 1, 64).encode('ascii', errors='ignore'))
            elif choice == 1:
                chunks.append(_make_utf8ish_bytes(rng, 8, 64))
            elif choice == 2:
                chunks.append(_make_punct(rng, 1, 32).encode('ascii', errors='ignore'))
            elif choice == 3:
                chunks.append(_make_whitespacey(rng, 0, 16).encode('ascii', errors='ignore'))
            elif choice == 4:
                chunks.append(_interval_spec(rng).encode('utf-8', errors='ignore'))
            else:
                chunks.append(_set_spec(rng).encode('utf-8', errors='ignore'))

    out = _bounded_concat(chunks, _MAX_SIZE)
    if not out:
        # Ensure non-empty by default
        out = b"x"
    return out

def _whitespace_pad(rng: random.Random, s: str) -> str:
    return _make_whitespacey(rng, 0, 4) + s + _make_whitespacey(rng, 0, 4)
